<?php
namespace App\Http\Controllers;use App\Models\{Program,Department};use Illuminate\Http\Request;class ProgramController extends Controller{public function index(Request $r){$q=Program::with('department')->where('is_active',true);if($r->filled('department'))$q->where('department_id',$r->integer('department'));return view('programs.index',['items'=>$q->orderBy('sort')->get(),'departments'=>Department::where('is_active',true)->orderBy('sort')->get()]);}public function show(Program $program){abort_unless($program->is_active,404);$program->load('department');return view('programs.show',compact('program'));}}